library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

package king_wen_shotgun_pkg is

    ---------------------------------------------------------------------------
    -- Fixed-point types
    ---------------------------------------------------------------------------
    subtype t_q88 is signed(15 downto 0);     -- Q8.8 signed
    subtype t_uq88 is unsigned(15 downto 0);  -- Q8.8 unsigned
    subtype t_uq016 is unsigned(15 downto 0); -- Q0.16 unsigned

    ---------------------------------------------------------------------------
    -- Hexagram record: all 26 fields packed
    ---------------------------------------------------------------------------
    type t_hexagram is record
        id              : unsigned(6 downto 0);   -- 1..64
        yao             : unsigned(5 downto 0);   -- binary pattern
        upper_trigram   : unsigned(2 downto 0);   -- Qian=0..Li=7
        lower_trigram   : unsigned(2 downto 0);
        category        : unsigned(1 downto 0);   -- sovereign=0..boundary=3
        action          : unsigned(1 downto 0);   -- ASSERT=0..WAIT=3
        agent           : unsigned(1 downto 0);   -- architect=0..guardian=3
        domain          : unsigned(1 downto 0);   -- assertion=0..patience=3
        element         : unsigned(2 downto 0);   -- heaven=0..fire=7
        coder           : unsigned(3 downto 0);   -- 12 specialties
        rs3             : unsigned(3 downto 0);   -- 10 RS3 actionables
        motion          : std_logic;              -- 0=centripetal, 1=centrifugal
        voice           : unsigned(3 downto 0);   -- 9 voice modes
        intent          : unsigned(3 downto 0);   -- understand=0
        density         : unsigned(1 downto 0);   -- OEIS A000000: 0=valley,1=terrace,2=peak
        vortex_tension  : t_q88;                  -- Schauberger physics
        suction         : t_uq88;
        chaos           : t_uq016;                -- Emotional vector (5D)
        whimsy          : t_uq016;
        dark            : t_uq016;
        coherence       : t_uq016;
        voice_weight    : t_uq016;
        intensity       : t_uq016;
        tx              : t_q88;                  -- Terrain coordinates
        ty              : t_q88;
    end record;

    ---------------------------------------------------------------------------
    -- Array types for shotgun output
    ---------------------------------------------------------------------------
    type t_hexagram_array is array (0 to 63) of t_hexagram;
    type t_density_array is array (0 to 63) of unsigned(1 downto 0);
    type t_coupling_matrix is array (0 to 3, 0 to 3) of unsigned(7 downto 0); -- Q0.8

    ---------------------------------------------------------------------------
    -- Category coupling strengths (from dashboard: SOV↔DISS=0.90, etc.)
    -- Stored as Q0.8: 0.90 = 230, 0.50 = 128, 0.10 = 26, etc.
    ---------------------------------------------------------------------------
    constant C_COUPLING : t_coupling_matrix := (
        --              SOV    DISS   TRANS  BOUND
